package main

import (
	"flag"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type GlobalFlags struct {
	Backend            string
	BackendS3Bucket    string
	KmsKeyAlias        string
	Retries            int
	RetryMode          string
	Verbose            bool
}

type FlagParser struct {
	args        []string
	globalFlags *GlobalFlags
	idx         int
}

func NewFlagParser(args []string) *FlagParser {
	return &FlagParser{
		args: args,
		globalFlags: &GlobalFlags{
			Backend:     "ssm",
			KmsKeyAlias: "alias/parameter_store_key",
			Retries:     10,
			RetryMode:   "standard",
		},
		idx: 0,
	}
}

func (fp *FlagParser) ParseGlobalFlags() {
	for fp.idx < len(fp.args) {
		arg := fp.args[fp.idx]

		if !strings.HasPrefix(arg, "-") {
			break
		}

		if arg == "--help" || arg == "-h" {
			if strings.Contains(arg, "=") {
				// Ignore if it's part of another flag
				fp.idx++
				continue
			}
			return
		}

		switch {
		case arg == "-b" || arg == "--backend":
			fp.idx++
			if fp.idx < len(fp.args) {
				fp.globalFlags.Backend = fp.args[fp.idx]
			}
		case strings.HasPrefix(arg, "--backend="):
			fp.globalFlags.Backend = arg[len("--backend="):]
		case arg == "--backend-s3-bucket":
			fp.idx++
			if fp.idx < len(fp.args) {
				fp.globalFlags.BackendS3Bucket = fp.args[fp.idx]
			}
		case strings.HasPrefix(arg, "--backend-s3-bucket="):
			fp.globalFlags.BackendS3Bucket = arg[len("--backend-s3-bucket="):]
		case arg == "--kms-key-alias":
			fp.idx++
			if fp.idx < len(fp.args) {
				fp.globalFlags.KmsKeyAlias = fp.args[fp.idx]
			}
		case strings.HasPrefix(arg, "--kms-key-alias="):
			fp.globalFlags.KmsKeyAlias = arg[len("--kms-key-alias="):]
		case arg == "-r" || arg == "--retries":
			fp.idx++
			if fp.idx < len(fp.args) {
				r, _ := strconv.Atoi(fp.args[fp.idx])
				fp.globalFlags.Retries = r
			}
		case strings.HasPrefix(arg, "--retries="):
			r, _ := strconv.Atoi(arg[len("--retries="):])
			fp.globalFlags.Retries = r
		case arg == "--retry-mode":
			fp.idx++
			if fp.idx < len(fp.args) {
				fp.globalFlags.RetryMode = fp.args[fp.idx]
			}
		case strings.HasPrefix(arg, "--retry-mode="):
			fp.globalFlags.RetryMode = arg[len("--retry-mode="):]
		case arg == "--verbose":
			fp.globalFlags.Verbose = true
		default:
			fp.idx++
			continue
		}

		fp.idx++
	}
}

func (fp *FlagParser) RemainingArgs() []string {
	return fp.args[fp.idx:]
}

func parseListFlags(args []string) (service string, expand, sortByTime, sortByUser, sortByVersion bool, remainingArgs []string) {
	fs := flag.NewFlagSet("list", flag.ContinueOnError)
	fs.Usage = func() {}

	e := fs.Bool("e", false, "expand")
	el := fs.Bool("expand", false, "expand")
	t := fs.Bool("t", false, "time")
	tl := fs.Bool("time", false, "time")
	u := fs.Bool("u", false, "user")
	ul := fs.Bool("user", false, "user")
	v := fs.Bool("v", false, "version")
	vl := fs.Bool("version", false, "version")
	h := fs.Bool("h", false, "help")
	hl := fs.Bool("help", false, "help")

